examples.template:
MonarchCallStatsPanel(
    usage: MonarchCallStatsPanelUsage(
        sentBytes: {{usage.sentBytes}},
        receivedBytes: {{usage.receivedBytes}},
        upBitsPerSecond: {{usage.upBps|double}},
        downBitsPerSecond: {{usage.downBps|double}}
    ),
    peers: [
        MonarchCallStatsPanelPeer(id: {{peers.0.id}}, name: {{peers.0.name}}, roundTripMilliseconds: {{peers.0.rttMs|double}}, inboundLossPercent: {{peers.0.inboundLossPct|double}}, outboundLossPercent: {{peers.0.outboundLossPct|double}}, quality: {{peers.0.quality|case}}),
        MonarchCallStatsPanelPeer(id: {{peers.1.id}}, name: {{peers.1.name}}, roundTripMilliseconds: {{peers.1.rttMs|double}}, inboundLossPercent: {{peers.1.inboundLossPct|double}}, outboundLossPercent: {{peers.1.outboundLossPct|double}}, quality: {{peers.1.quality|case}}),
        MonarchCallStatsPanelPeer(id: {{peers.2.id}}, name: {{peers.2.name}}, quality: {{peers.2.quality|case}}),
    ],
    footnote: {{footnote}}
)

examples.code:
MonarchButton("Show connection", variant: .secondary) { showsStats = true }
    .sheet(isPresented: $showsStats) {
        NavigationStack {
            ScrollView {
                MonarchCallStatsPanel(usage: usage, peers: [], isLowData: true)
                    .padding()
            }
            .navigationTitle("Connection")
        }
        .presentationDetents([.medium, .large])
    }
